1	//! The first search stage: walks a root and returns, per file, the lines that match any query pattern.
2	
3	use std::collections::BTreeMap;
4	use std::io;
5	use std::sync::{Arc, Mutex};
6	
7	use camino::{Utf8Path, Utf8PathBuf};
8	use grep_regex::{RegexMatcher, RegexMatcherBuilder};
9	use grep_searcher::{BinaryDetection, Searcher, SearcherBuilder, Sink, SinkContext, SinkMatch};
10	use ignore::WalkBuilder;
11	use ignore::gitignore::Gitignore;
12	use rayon::prelude::*;
13	use rustc_hash::FxHashMap;
14	
15	use crate::error::{MonoklError, Result};
16	use crate::types::LineHit;
17	
18	/// How many files each thread searches per batch. A batch ends in a wait for its slowest file, so a small batch costs
19	/// speed; a large one holds more hits at once.
20	const BATCH_FILES_PER_THREAD: usize = 16;
21	
22	/// The default for [`TextSearchOptions::max_files`].
23	pub const DEFAULT_MAX_FILES: usize = 100_000;
24	
25	/// Options for [`search_files`].
26	///
27	/// # Examples
28	///
29	/// ```
30	/// use monokl::text_search::TextSearchOptions;
31	///
32	/// let opts = TextSearchOptions { allow_tests: true, ..TextSearchOptions::default() };
33	/// assert!(opts.respect_ignore_files);
34	/// ```
35	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
36	pub struct TextSearchOptions {
37	    /// Searches test files too. When false, a file is skipped if its path below the root has a `__tests__`, `test`,
38	    /// `tests` or `spec` directory, or ends in `.test.ts`, `.test.tsx`, `.test.js`, `.spec.ts`, `.spec.tsx` or
39	    /// `.spec.js`. Matching is case-sensitive.
40	    pub allow_tests: bool,
41	    /// Skips hidden files and what `.gitignore` and `.ignore` files inside the root exclude, with or without a `.git`
42	    /// directory. When the root lies inside a git repository (the nearest ancestor with a `.git` entry), the
43	    /// `.gitignore` and `.ignore` files of the directories from the repository root down to the root's parent apply
44	    /// too, as they do for ripgrep, and rules inside the root take precedence over them. Nothing above the repository
45	    /// root is read, and without a `.git` ancestor no parent is read. `.git/info/exclude` and the user's global
46	    /// excludes are never read, so the same checkout gives the same result on every machine.
47	    pub respect_ignore_files: bool,
48	    /// The most files whose hits are kept. Matching files past it are still searched and counted.
49	    pub max_files: usize,
50	}
51	
52	impl Default for TextSearchOptions {
53	    /// Skips tests, honors ignore files and keeps up to [`DEFAULT_MAX_FILES`] files.
54	    fn default() -> Self {
55	        Self { allow_tests: false, respect_ignore_files: true, max_files: DEFAULT_MAX_FILES }
56	    }
57	}
58	
59	/// What [`search_files`] found.
60	#[derive(Clone, Debug, Default, PartialEq, Eq)]
61	#[non_exhaustive]
62	pub struct TextSearchResult {
63	    /// The kept files, keyed by `root` joined with the path below it, each with its matching lines in line order.
64	    pub hits: BTreeMap<Utf8PathBuf, Vec<LineHit>>,
65	    /// Every file with at least one matching line, kept or not.
66	    pub files_total: u64,
67	    /// Whether `files_total` exceeded [`TextSearchOptions::max_files`], so some matching files have no hits stored.
68	    pub ceiling_hit: bool,
69	    /// In walk order and each listed once, keyed like `hits`: files that could not be read, directories that could not
70	    /// be listed, and ignore files that could not be read or parsed. A parent ignore file above the root is named by its
71	    /// canonical path.
72	    pub unreadable: Vec<Utf8PathBuf>,
73	    /// How many regular files were skipped because their path is not UTF-8.
74	    pub non_utf8_paths: u64,
75	    /// How many walk errors below the root carried no UTF-8 path to put in `unreadable`.
76	    pub walk_errors_without_path: u64,
77	}
78	
79	/// Searches every regular file under `root` for lines matching any of `patterns`, regexes matched case-insensitively
80	/// with Unicode case folding.
81	///
82	/// A pattern sees each line without its `\n` or `\r\n` terminator, exactly the text a hit reports, so `^` and `$`
83	/// anchor at the line's start and end in LF and CRLF files alike, and a pattern for `\n` matches no line.
84	///
85	/// Each directory's entries are visited in byte order of their file names, so the result is the same on every run.
86	/// Symbolic links are neither followed nor searched. Binary files (any NUL byte) are skipped silently, even when a
87	/// matching line is also not UTF-8. A matching line that is not UTF-8 is a hit with each invalid byte sequence
88	/// replaced by U+FFFD. A file that cannot be read, and any walk failure below `root`, go in
89	/// [`unreadable`](TextSearchResult::unreadable) and the search continues. No patterns
90	/// means nothing to search: once `root` is checked, the result is empty and nothing is walked.
91	///
92	/// # Errors
93	///
94	/// - [`MonoklError::RegexBuild`] if any pattern does not compile, before `root` is checked.
95	/// - [`MonoklError::Walk`] with `path` set to `root` if `root` is missing, is not a directory or cannot be listed,
96	///   even when there are no patterns.
97	///
98	/// # Examples
99	///
100	/// ```
101	/// use camino::Utf8Path;
102	/// use monokl::text_search::{search_files, TextSearchOptions};
103	///
104	/// let dir = tempfile::tempdir()?;
105	/// std::fs::write(dir.path().join("a.ts"), "const Alpha = 1;\nconst beta = 2;\n")?;
106	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
107	///
108	/// let result = search_files(root, &["alpha", "gamma"], &TextSearchOptions::default())?;
109	/// let lines = &result.hits[&root.join("a.ts")];
110	/// assert_eq!((lines[0].line_number, lines[0].text.as_str()), (1, "const Alpha = 1;"));
111	/// assert_eq!(result.files_total, 1);
112	/// # Ok::<(), Box<dyn std::error::Error>>(())
113	/// ```
114	pub fn search_files(root: &Utf8Path, patterns: &[&str], opts: &TextSearchOptions) -> Result<TextSearchResult> {
115	    search_in_batches(root, patterns, opts, rayon::current_num_threads() * BATCH_FILES_PER_THREAD)
116	}
117	
118	/// [`search_files`] with the number of files searched before their outcomes are folded into the result. The result does
119	/// not depend on it; it bounds how many files' hits are held beyond the kept ones.
120	fn search_in_batches(
121	    root: &Utf8Path,
122	    patterns: &[&str],
123	    opts: &TextSearchOptions,
124	    batch_size: usize,
125	) -> Result<TextSearchResult> {
126	    let matcher = compile(patterns)?;
127	    let root_error = |source| MonoklError::Walk { path: root.to_owned(), source };
128	    let metadata = std::fs::metadata(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
129	    if !metadata.is_dir() {
130	        return Err(root_error(ignore::Error::Io(io::Error::from(io::ErrorKind::NotADirectory))));
131	    }
132	    // Listed here as well as by the walk, so a root that cannot be listed fails even when there is nothing to search.
133	    std::fs::read_dir(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
134	    let mut result = TextSearchResult::default();
135	    let Some(matcher) = matcher else {
136	        return Ok(result);
137	    };
138	    // Passthru hands every line to the sink, so a CRLF line the matcher rejected because it saw the `\r` can still be
139	    // checked against its text without the terminator. BOM sniffing is off so a UTF-16 file's NUL bytes mark it binary
140	    // and a UTF-8 BOM stays in the first line's text instead of being decoded away.
141	    let mut searcher_builder = SearcherBuilder::new();
142	    searcher_builder.binary_detection(BinaryDetection::quit(b'\x00')).bom_sniffing(false).passthru(true);
143	    // The `ignore` crate's own parent support reads every ancestor up to `/`, so the walk covers the root and the
144	    // repository's parent files are applied by `ParentIgnores`. Global and `.git/info/exclude` rules stay off so the
145	    // same checkout gives the same result on every machine.
146	    let parents = if opts.respect_ignore_files { ParentIgnores::load(root, &mut result) } else { None };
147	    let mut builder = WalkBuilder::new(root);
148	    builder
149	        .standard_filters(opts.respect_ignore_files)
150	        .parents(false)
151	        .git_global(false)
152	        .git_exclude(false)
153	        .require_git(false)
154	        .sort_by_file_name(std::cmp::Ord::cmp);
155	    if let Some(parents) = parents {
156	        let root = root.to_owned();
157	        builder.filter_entry(move |entry| {
158	            let Some(path) = Utf8Path::from_path(entry.path()) else { return true };
159	            let Ok(relative) = path.strip_prefix(&root) else { return true };
160	            !parents.excludes(relative, entry.file_type().is_some_and(|file_type| file_type.is_dir()))
161	        });
162	    }
163	    let walk = builder.build();
164	    // Walk errors and files keep the position they had in the walk, so `unreadable` lists them in walk order.
165	    let mut items = Vec::new();
166	    for entry in walk {
167	        let entry = match entry {
168	            Ok(entry) => entry,
169	            Err(err) if err.depth() == Some(0) => return Err(root_error(err)),
170	            Err(err) => {
171	                collect_walk_error(&err, &mut items);
172	                continue;
173	            }
174	        };
175	        if let Some(err) = entry.error() {
176	            collect_walk_error(err, &mut items);
177	        }
178	        if !entry.file_type().is_some_and(|file_type| file_type.is_file()) {
179	            continue;
180	        }
181	        let Ok(path) = Utf8PathBuf::from_path_buf(entry.into_path()) else {
182	            result.non_utf8_paths += 1;
183	            continue;
184	        };
185	        if !opts.allow_tests && is_test_path(path.strip_prefix(root).unwrap_or(&path)) {
186	            continue;
187	        }
188	        items.push(WalkItem::File(path));
189	    }
190	    // Files are searched on separate threads a batch at a time and folded in walk order, so the result and the ceiling
191	    // never depend on which thread finished first. A file's hits are dropped as soon as it is past the ceiling, so one
192	    // batch's hits are held beyond the kept files, however many files match.
193	    let batch_size = batch_size.max(1);
194	    let mut items = items.into_iter();
195	    loop {
196	        let batch: Vec<WalkItem> = items.by_ref().take(batch_size).collect();
197	        if batch.is_empty() {
198	            break;
199	        }
200	        let searched: Vec<Searched> = batch
201	            .into_par_iter()
202	            .map_init(
203	                || searcher_builder.build(),
204	                |searcher, item| match item {
205	                    WalkItem::File(path) => {
206	                        let outcome = search_file(searcher, &matcher, &path);
207	                        Searched::File(path, outcome)
208	                    }
209	                    WalkItem::WalkError(error) => Searched::WalkError(error),
210	                },
211	            )
212	            .collect();
213	        for item in searched {
214	            match item {
215	                Searched::WalkError(error) => error.record(&mut result),
216	                Searched::File(_, FileOutcome::Binary) => {}
217	                Searched::File(path, FileOutcome::Unreadable) => result.unreadable.push(path),
218	                Searched::File(path, FileOutcome::Lines(hits)) => {
219	                    if hits.is_empty() {
220	                        continue;
221	                    }
222	                    result.files_total += 1;
223	                    if result.hits.len() < opts.max_files {
224	                        result.hits.insert(path, hits);
225	                    } else {
226	                        result.ceiling_hit = true;
227	                    }
228	                }
229	            }
230	        }
231	    }
232	    Ok(result)
233	}
234	
235	/// The `.ignore` and `.gitignore` rules of the directories from a git repository's root down to the search root's
236	/// parent, applied as the `ignore` crate applies parent files: a rule nearer the entry wins, `.ignore` wins over
237	/// `.gitignore` in one directory, and rules inside the search root win over all of them.
238	struct ParentIgnores {
239	    /// The canonical search root, which the matchers' paths are built from.
240	    base: Utf8PathBuf,
241	    /// Nearest directory first.
242	    parents: Vec<DirRules>,
243	    /// Rules of the directories inside the root, read when first needed.
244	    inside: Mutex<FxHashMap<Utf8PathBuf, Arc<DirRules>>>,
245	}
246	
247	/// One directory's `.ignore` and `.gitignore` files.
248	struct DirRules {
249	    ignore: Gitignore,
250	    gitignore: Gitignore,
251	}
252	
253	impl DirRules {
254	    /// Reads the directory's rules, with the errors from files that could not be read or parsed.
255	    fn read(dir: &Utf8Path) -> (Self, Vec<ignore::Error>) {
256	        let (ignore, ignore_err) = Gitignore::new(dir.join(".ignore"));
257	        let (gitignore, gitignore_err) = Gitignore::new(dir.join(".gitignore"));
258	        (Self { ignore, gitignore }, ignore_err.into_iter().chain(gitignore_err).collect())
259	    }
260	
261	    /// Whether either file has a rule, ignoring or whitelisting, that matches. `Some(true)` is an ignore.
262	    fn verdict(&self, path: &Utf8Path, is_dir: bool) -> Option<bool> {
263	        let matched =
264	            self.ignore.matched(path, is_dir).map(|_| ()).or(self.gitignore.matched(path, is_dir).map(|_| ()));
265	        match matched {
266	            ignore::Match::None => None,
267	            ignore::Match::Ignore(()) => Some(true),
268	            ignore::Match::Whitelist(()) => Some(false),
269	        }
270	    }
271	}
272	
273	impl ParentIgnores {
274	    /// Reads the parent rules for `root`, or `None` when `root` has no `.git` ancestor, is itself the repository
275	    /// root, or no parent directory has a rule. Read errors go in `result` like walk errors do.
276	    fn load(root: &Utf8Path, result: &mut TextSearchResult) -> Option<Self> {
277	        let base = root.canonicalize_utf8().ok()?;
278	        let repo_root = base.ancestors().find(|dir| dir.join(".git").symlink_metadata().is_ok())?;
279	        let mut parents = Vec::new();
280	        for dir in base.ancestors().skip(1).take_while(|dir| dir.starts_with(repo_root)) {
281	            let (rules, errors) = DirRules::read(dir);
282	            for err in &errors {
283	                record_walk_error(err, result);
284	            }
285	            parents.push(rules);
286	        }
287	        parents.iter().any(|rules| !rules.ignore.is_empty() || !rules.gitignore.is_empty()).then(|| Self {
288	            base,
289	            parents,
290	            inside: Mutex::new(FxHashMap::default()),
291	        })
292	    }
293	
294	    /// Whether a parent rule excludes the entry at `relative` below the root, and no rule inside the root matches it.
295	    fn excludes(&self, relative: &Utf8Path, is_dir: bool) -> bool {
296	        if relative.as_str().is_empty() {
297	            return false;
298	        }
299	        let path = self.base.join(relative);
300	        let decided_inside = path
301	            .ancestors()
302	            .skip(1)
303	            .take_while(|dir| dir.starts_with(&self.base))
304	            .any(|dir| self.inside_rules(dir).verdict(&path, is_dir).is_some());
305	        if decided_inside {
306	            return false;
307	        }
308	        self.parents.iter().find_map(|rules| rules.verdict(&path, is_dir)).unwrap_or(false)
309	    }
310	
311	    fn inside_rules(&self, dir: &Utf8Path) -> Arc<DirRules> {
312	        let mut cache = self.inside.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
313	        // Read errors are dropped: the walk reads the same files and reports them.
314	        Arc::clone(cache.entry(dir.to_owned()).or_insert_with(|| Arc::new(DirRules::read(dir).0)))
315	    }
316	}
317	
318	/// Compiles each pattern alone, then all together, so an invalid one always fails the search. `None` when there are no
319	/// patterns.
320	fn compile(patterns: &[&str]) -> Result<Option<RegexMatcher>> {
321	    let mut builder = RegexMatcherBuilder::new();
322	    builder.case_insensitive(true);
323	    // `build_many` joins the patterns with `|` before parsing, so halves such as `(a` and `b)` would compile together.
324	    for pattern in patterns {
325	        builder.build(pattern)?;
326	    }
327	    if patterns.is_empty() {
328	        return Ok(None);
329	    }
330	    Ok(Some(builder.build_many(patterns)?))
331	}
332	
333	/// Lists the path a walk error names in `unreadable`, or counts it when it names none that is UTF-8.
334	fn record_walk_error(err: &ignore::Error, result: &mut TextSearchResult) {
335	    let mut items = Vec::new();
336	    collect_walk_error(err, &mut items);
337	    for item in items {
338	        match item {
339	            WalkItem::WalkError(error) => error.record(result),
340	            WalkItem::File(_) => {}
341	        }
342	    }
343	}
344	
345	/// Appends one item per path a walk error names, or per failure that names no UTF-8 path.
346	fn collect_walk_error(err: &ignore::Error, items: &mut Vec<WalkItem>) {
347	    match err {
348	        ignore::Error::Partial(errs) => {
349	            for err in errs {
350	                collect_walk_error(err, items);
351	            }
352	        }
353	        ignore::Error::WithPath { path, .. } | ignore::Error::Loop { child: path, .. } => {
354	            items.push(WalkItem::WalkError(match Utf8Path::from_path(path) {
355	                Some(path) => WalkError::Path(path.to_owned()),
356	                None => WalkError::WithoutPath,
357	            }));
358	        }
359	        ignore::Error::WithDepth { err, .. } | ignore::Error::WithLineNumber { err, .. } => {
360	            collect_walk_error(err, items);
361	        }
362	        ignore::Error::Io(_)
363	        | ignore::Error::Glob { .. }
364	        | ignore::Error::UnrecognizedFileType(_)
365	        | ignore::Error::InvalidDefinition => items.push(WalkItem::WalkError(WalkError::WithoutPath)),
366	    }
367	}
368	
369	/// What the walk produced, in the order it produced it.
370	enum WalkItem {
371	    File(Utf8PathBuf),
372	    WalkError(WalkError),
373	}
374	
375	/// One failure the walk reported.
376	enum WalkError {
377	    Path(Utf8PathBuf),
378	    WithoutPath,
379	}
380	
381	impl WalkError {
382	    /// Lists the path once, or counts a failure that names no UTF-8 path.
383	    fn record(self, result: &mut TextSearchResult) {
384	        match self {
385	            Self::Path(path) if result.unreadable.contains(&path) => {}
386	            Self::Path(path) => result.unreadable.push(path),
387	            Self::WithoutPath => result.walk_errors_without_path += 1,
388	        }
389	    }
390	}
391	
392	/// A [`WalkItem`] after its file, if any, has been searched.
393	enum Searched {
394	    File(Utf8PathBuf, FileOutcome),
395	    WalkError(WalkError),
396	}
397	
398	/// How searching one file ended.
399	enum FileOutcome {
400	    Binary,
401	    Unreadable,
402	    /// The file's matching lines, possibly none.
403	    Lines(Vec<LineHit>),
404	}
405	
406	fn search_file(searcher: &mut Searcher, matcher: &RegexMatcher, path: &Utf8Path) -> FileOutcome {
407	    let mut sink = LineCollector::new(matcher);
408	    match searcher.search_path(matcher, path.as_std_path(), &mut sink) {
409	        Err(_) => FileOutcome::Unreadable,
410	        Ok(()) if sink.binary => FileOutcome::Binary,
411	        Ok(()) => FileOutcome::Lines(sink.hits),
412	    }
413	}
414	
415	/// Collects matching lines, and stops at the first sign of binary data so the caller can discard the whole file,
416	/// including lines matched before the NUL byte was reached. A matching line that is not UTF-8 is kept with its invalid
417	/// bytes replaced by U+FFFD, and does not stop the search, so a NUL later in the file still marks it binary.
418	///
419	/// The searcher strips only the `\n` before matching, so a line ending in `\r\n` is matched again here against its
420	/// text without the terminator: a pattern always sees exactly the text a hit reports.

