import pathlib
import statistics
import subprocess
import time

root = pathlib.Path("target/synth").resolve()
if not root.exists():
    for d in range(30):
        (root / f"d{d:02}").mkdir(parents=True)
    for i in range(30000):
        ext = "txt" if i % 2 else "json"
        (root / f"d{i % 30:02}" / f"f{i}.{ext}").write_text(f"some line\nneedle value {i}\nmore text here\n" * 3)
    for i in range(3000):
        (root / f"d{i % 30:02}" / f"s{i}.ts").write_text(
            f"export function needle{i}(a: number) {{\n  return a + {i};\n}}\n\nconst other{i} = 1;\n"
        )

bins = {"old": pathlib.Path("target/bench/o/monokl").resolve(), "new": pathlib.Path("target/bench/n/monokl").resolve()}
zod = pathlib.Path("target/rg-compare/zod").resolve()
runs = [("synthetic", root, ["needle", "."]), ("zod", zod, ["ZodType", "."]), ("zod packages/zod/src", zod, ["ZodType", "packages/zod/src"])]
for label, cwd, args in runs:
    res = {}
    for name, b in bins.items():
        subprocess.run([str(b), "search", *args], cwd=cwd, capture_output=True)
        times = []
        for _ in range(20):
            t = time.perf_counter()
            subprocess.run([str(b), "search", *args], cwd=cwd, capture_output=True)
            times.append((time.perf_counter() - t) * 1000)
        res[name] = statistics.median(times)
    print(label, {k: round(v, 1) for k, v in res.items()})

